                if neighbor < node:
                    continue
                clause = [-node - 1, -neighbor - 1]
                if is_valid_clause(clause):
                    cnf.append(clause)
        return cnf

    def count_lattice_points(graph):
        n = len(graph)
        d = sum(len(neighbors) for neighbors in graph.values()) // n
        lattice_points = set()
        for node in range(n):
            for i in range(1 << d):
                point = [0] * d
